UPDATE `tt_content` SET `bodytext`='<style>\r\n#img1 {\r\n  display: block;\r\n}\r\n\r\nbody {\r\n  overflow-x: hidden;\r\n}\r\n\r\nh3, h4, main > a {\r\n  max-width: 100% !important;\r\n  font-size: 1.4em !important;\r\n  margin-top: 20px;\r\n}\r\n\r\nh2.heading {\r\n  max-width: 100% !important;\r\n  font-size: 1.8em !important;\r\n  margin: 0px 0px !important;\r\n  padding: 20px 0px !important;\r\n}\r\n\r\np {\r\n  max-width: 100% !important;\r\n  font-size: 1em;\r\n}\r\n\r\nmain > div > div > p > a {\r\n  color: #5bd688 !important;\r\n  font-style: normal;\r\n  font-size: 1rem;\r\n}\r\n\r\nmain a {\r\n  font-weight: regular;\r\n  color: #000000 !important;\r\n  text-decoration: none;\r\n}\r\n\r\nmain a:hover {\r\n  text-decoration: none;\r\n  color: #5BD688 !important;\r\n}\r\n\r\n#c2074921 {\r\n  text-align: center;\r\n}\r\n\r\n#c2075934 {\r\n  color: #5BD688;\r\n}\r\n\r\ndiv.csc-textpic-imagewrap {\r\n  max-width: 160px;\r\n}\r\n\r\n.mb-5 {\r\n  margin-bottom: 1rem !important;\r\n}\r\n\r\n.vd-list-links {\r\n  color: #5bd688;\r\n}\r\n\r\n@media only screen and (max-width: 768px) {\r\n  .csc-textpic csc-textpic-intext-left-nowrap {\r\n    text-align: center;\r\n  }\r\n}\r\n\r\n.btn-secondary {\r\n  background-color: #000000;\r\n  border: none !important;\r\n  box-shadow: none !important;\r\n  color: white !important;\r\n}\r\n\r\n.btn-secondary:hover {\r\n  background-color: #5BD688;\r\n  color: white !important;\r\n}\r\n\r\n.btn-dark {\r\n  background-color: #000000;\r\n  border: none !important;\r\n  box-shadow: none !important;\r\n}\r\n\r\n.btn-dark:hover {\r\n  background-color: #5BD688;\r\n  color: white !important;\r\n}\r\n\r\n.btn-secondary.violet:hover {\r\n  background-color: #7281bf;\r\n  color: white;\r\n}\r\n\r\n.btn-secondary.rouge:hover {\r\n  background-color: #cf392c;\r\n  color: white;\r\n}\r\n\r\n.btn-secondary.vert:hover {\r\n  background-color: #5bd688;\r\n  color: white;\r\n}\r\n\r\n.vd-frontend h3 span {\r\n  color: #5bd688;\r\n}\r\n\r\n.vd-frontend .btn-download {\r\n  font-size: 0.75rem;\r\n  padding: 0.3rem\r\n}\r\n</style>\r\n' WHERE `uid`=2074833;
UPDATE `tt_content` SET `bodytext`='<style>\r\n  \r\n  #vd-frontend-2076597 h3 a{\r\n    color: #000 !important;\r\n    }\r\n  \r\n  #vd-frontend-2076597 h3 a:hover{\r\n    color: #8fad56 !important;\r\n    }\r\n\r\n/*Bouton en savoir plus*/  \r\n   .btn-secondary {\r\n    background-color: #8fad56;\r\n    border: none !important;\r\n    box-shadow: none !important;\r\n    border-radius: 50px;\r\n    \r\n    }\r\n  \r\n   a.btn-secondary {\r\n    color: white !important;\r\n    text-transform: inherit;\r\n    }\r\n   a.btn-secondary:after{\r\n    content: \" →\";\r\n    }\r\n    \r\n  \r\n  .btn-secondary:hover{\r\n      background-color: black !important;\r\n      color:white !important;\r\n    }\r\n  \r\n  \r\n    #vd-frontend-2076597 .btn-dark {\r\n    background-color: #000;\r\n    border: none !important;\r\n    box-shadow: none !important;\r\n    border-radius: 50px;\r\n    \r\n    }\r\n  \r\n   #vd-frontend-2076597 a.btn-dark {\r\n    font-size: 1.8rem;\r\n    color: white !important;\r\n    padding: 10px 20px;\r\n    text-transform: inherit;\r\n    }\r\n   #vd-frontend-2076597 a.btn-dark:after{\r\n    content: \" →\";\r\n    }\r\n    \r\n  \r\n  #vd-frontend-2076597 .btn-dark:hover{\r\n      background-color: #8fad56 !important;\r\n      color:white !important;\r\n    }\r\n  \r\n  \r\n  #vd-frontend-2076597 .btn{\r\n    margin-top:15px !important;\r\n  }\r\n  \r\n/* Fin Bouton en savoir plus*/\r\n  \r\n  main a{\r\n    font-weight: regular;\r\n    color: #8fad56 !important;\r\n    text-decoration: none;\r\n    }\r\n  \r\n  main a:hover{\r\n    text-decoration: none;\r\n    color:black !important;\r\n    }\r\n  \r\n  .lien-nav a {color: white !important;}\r\n  .lien-nav:hover a {color: black !important;}\r\n\r\n/* Bouton dans les résultat */\r\n  \r\n  a.btn-cancel {\r\n    font-size: 1rem !important;\r\n    padding: 10px 20px !important;\r\n    }\r\n</style>' WHERE `uid`=2076549;
UPDATE `tt_content` SET `bodytext`='<style>\r\n  \r\n  h2{\r\n    font-size: 2.8rem;\r\n  }\r\n  \r\n  h3 {\r\n    font-size: 2rem;\r\n    color: #8fad56;\r\n    font-weight: bold; \r\n  }  \r\n \r\n  h4 {    \r\n    /*text-align: center;*/\r\n    color: #8fad56;\r\n    font-size: 1.5rem;  \r\n  }\r\n\r\n  h5{\r\n    font-weight: normal;\r\n    font-size: 1.2rem;\r\n    margin-bottom: 28px;\r\n  }\r\n  \r\n  main p{\r\n    max-width: 100% !important;\r\n    font-size: 1.2rem;\r\n  }\r\n  \r\n  main li {\r\n    max-width: 100% !important;\r\n    font-size: 1.2rem;\r\n    }\r\n  \r\n  .table-striped tbody tr:nth-of-type(odd){\r\n    font-size: 1.2rem;\r\n    }\r\n  \r\n  .list > li > h3 {\r\n    font-size: 1.5rem;\r\n    font-weight: bold;\r\n      }\r\n    \r\n  @media only screen and (max-width: 768px){\r\n  h2{font-size: 1.5rem;}\r\n  h3,\r\n  h4{font-size: 1rem;}\r\n  h5{font-size: 0.6rem;}\r\n  main p, .list > li > h3{font-size: 1rem;}\r\n  main li{font-size: 0.8rem;}\r\n  a.btn-secondary{font-size: 1rem !important;}\r\n  .table-striped tbody tr:nth-of-type(odd){font-size: 1rem;}\r\n  }\r\n\r\n</style>' WHERE `uid`=2076550;
UPDATE `tt_content` SET `bodytext`='<style>\r\n \r\n\r\n/* block image de fond */  \r\n  \r\n  .vd-highlight {\r\n    background-color: #8fad56;\r\n    }\r\n\r\n \r\n  .vd-highlight a.btn-secondary{\r\n    color: #8fad56!important;\r\n    background-color: #fff;\r\n    }\r\n  \r\n  .vd-highlight h2{\r\n    color: #fff;\r\n    margin-top: 40px;\r\n    font-weight: 600;\r\n    }\r\n  \r\n  .vd-highlight h3 {\r\n    color: #fff;\r\n    }\r\n    \r\n  .vd-highlight h4 {\r\n    color: white !important;\r\n    font-weight: 600;\r\n    }\r\n  \r\n  .vd-highlight a {\r\n    color: #fff !important;\r\n    }\r\n  \r\n  .vd-highlight .figure-caption {\r\n    color: white !important;\r\n    font-weight: 100;\r\n    }\r\n  \r\n  div > .vd-highlight {\r\n    padding: 2rem 9999%;\r\n    margin: 2rem -9999%;\r\n    }\r\n  \r\n  @media only screen and (max-width: 768px){\r\n  .vd-highlight {\r\n    padding: 20px 10px;\r\n    }\r\n  }\r\n  \r\n  /*matériel à télécharger */\r\n  \r\n  #c2071537 div.vd-highlight {\r\n    background-color: #8fad56;\r\n    }\r\n  #c2071537 {\r\n    margin-bottom: 0px !important;\r\n    }\r\n  \r\n/* fin block image de fond */\r\n  \r\n  .table-striped tbody tr:nth-of-type(odd){\r\n    background-color: #8fad56;\r\n    color: #fff;\r\n    }\r\n  \r\n/* block contact */ \r\n\r\n  #c2071441:before {\r\n    content: \"\";\r\n    background-color: #D3D3D3;\r\n    display: inline;\r\n    position: absolute;\r\n    height: 100%;\r\n    width: 5000px;\r\n    left: -2000px;\r\n    z-index: -1;\r\n    padding: 15px 0px !important;\r\n    }\r\n  \r\n #c2071441 {\r\n    position: relative;\r\n    color: black !important;\r\n    padding: 15px 0px !important;\r\n    }\r\n  #c2071441{\r\n    color: #000;\r\n    }\r\n  \r\n  #vd-frontend-2076597, #c2076709 {\r\n    background-color: #ecf9ea;\r\n    padding: 20px;\r\n    margin-top: 0px !important;\r\n    margin-bottom: 0px !important;\r\n    }\r\n  \r\n  .list > li {\r\n    margin-bottom: 80px !important;\r\n \r\n</style>' WHERE `uid`=2076551;
